?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard | StudentHub</title><link rel="stylesheet" href="event_admin.css"></head><body><main class="page"><div class="toolbar"><div><p class="eyebrow">ADMIN DASHBOARD</p><h1>Event management</h1><p class="muted">Welcome, <?=htmlspecialchars($_SESSION['admin_name'], ENT_QUOTES, 'UTF-8')?>. Create and manage StudentHub events.</p></div><div class="event-actions"><a class="button primary" href="event_form.php">Create event</a><a class="button secondary" href="logout.php">Logout</a></div></div><?php if($message==='created'): ?><p class="notice success">Event created successfully.</p><?php elseif($message==='updated'): ?><p class="notice success">Event updated successfully.</p><?php elseif($message==='deleted'): ?><p class="notice success">Event deleted successfully.</p><?php elseif($message==='error'): ?><p class="notice error">The requested event operation could not be completed.</p><?php endif; ?><section class="panel"><h2>Event list</h2><div class="event-grid"><?php if(!$events || mysqli_num_rows($events)===0): ?><p class="muted">No events have been created yet.</p><?php else: while($event=mysqli_fetch_assoc($events)): ?><article class="event-card"><?php if($event['poster']): ?><img src="uploads/posters/<?=htmlspecialchars($event['poster'], ENT_QUOTES, 'UTF-8')?>" alt="Poster for <?=htmlspecialchars($event['title'], ENT_QUOTES, 'UTF-8')?>"><?php else: ?><div class="event-card img-placeholder">No poster uploaded</div><?php endif; ?><div class="event-body"><p class="event-date"><?=htmlspecialchars(date('d M Y', strtotime($event['event_date'])), ENT_QUOTES, 'UTF-8')?></p><h3><?=htmlspecialchars($event['title'], ENT_QUOTES, 'UTF-8')?></h3><p><?=nl2br(htmlspecialchars($event['description'], ENT_QUOTES, 'UTF-8'))?></p><div class="event-actions"><a class="button secondary" href="event_form.php?id=<?=(int)$event['event_id']?>">Edit</a><a class="button danger" href="delete_event.php?id=<?=(int)$event['event_id']?>" onclick="return confirm('Delete this event permanently?');">Delete</a></div></div></article><?php endwhile; endif; ?></div></section></main></body></html>
